//! Python-vs-Rust parity sweep for the MeterRouter port.
//!
//! Reads `parity_cases.txt` (generated by `../parity_dump.py`):
//!   C: call-cost cases -- exact f64 equality.
//!   E: expected-success cases for single-agent teams -- within 1e-6
//!      (Rust uses an erf approximation; see lib.rs).
//!   Q: router cases -- team and stop must match exactly, cost
//!      exactly, expected success within 1e-6.

use meter_router::{
    call_cost, expected_team_success, greedy_router, team_cost, Agent, ROLES,
};

fn parse_f64(s: &str) -> f64 {
    s.parse::<f64>().unwrap()
}

fn role_idx(name: &str) -> usize {
    ROLES.iter().position(|r| *r == name).unwrap()
}

fn parse_team(s: &str) -> Vec<Agent> {
    if s.trim().is_empty() || s.trim() == "-" {
        return Vec::new();
    }
    s.split(';')
        .map(|part| {
            let fields: Vec<&str> = part.split(',').collect();
            let role = role_idx(fields[0]);
            let tier: usize = fields[1].parse().unwrap();
            let parents: Vec<usize> = if fields.len() > 2 && !fields[2].is_empty() {
                fields[2..].iter().map(|p| p.parse().unwrap()).collect()
            } else {
                Vec::new()
            };
            Agent::new(role, tier, &parents)
        })
        .collect()
}

#[test]
fn parity_sweep() {
    let text = include_str!("parity_cases.txt");
    let mut n_c = 0usize;
    let mut n_e = 0usize;
    let mut n_q = 0usize;
    let mut mismatches: Vec<String> = Vec::new();

    for (lineno, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (head, tail) = line.split_once(" | ").expect("missing | separator");
        let h: Vec<&str> = head.split_whitespace().collect();
        match h[0] {
            "C" => {
                n_c += 1;
                let tier: usize = h[1].parse().unwrap();
                let n_parents: usize = h[2].parse().unwrap();
                let role: usize = h[3].parse().unwrap();
                let want = parse_f64(tail.strip_prefix("COST ").unwrap());
                let got = call_cost(tier, n_parents, role);
                if got.to_bits() != want.to_bits() {
                    mismatches.push(format!(
                        "line {lineno}: C tier={tier} parents={n_parents} role={role}: got {got:?} want {want:?}"
                    ));
                }
            }
            "E" => {
                n_e += 1;
                let role: usize = h[1].parse().unwrap();
                let tier: usize = h[2].parse().unwrap();
                let diff = h[3];
                let n_pred: usize = h[4].parse().unwrap();
                let want = parse_f64(tail.strip_prefix("EXP ").unwrap());
                let team = vec![Agent::new(role, tier, &(0..n_pred).collect::<Vec<usize>>())];
                let got = expected_team_success(&team, diff);
                if (got - want).abs() > 1e-6 {
                    mismatches.push(format!(
                        "line {lineno}: E role={role} tier={tier} {diff} pred={n_pred}: got {got:.9} want {want:.9}"
                    ));
                }
            }
            "Q" => {
                n_q += 1;
                let diff = h[1];
                let budget = parse_f64(h[2]);
                let mode = h[3];
                let draws: Vec<usize> = h[4..]
                    .iter()
                    .map(|d| d.parse::<usize>().unwrap())
                    .collect();
                // tail: TEAM <team> STOP <stop> EXP <exp> COST <cost>
                let parts: Vec<&str> = tail.split_whitespace().collect();
                assert_eq!(parts[0], "TEAM");
                let team_s = parts[1];
                let stop_want = parts[3];
                let exp_want = parse_f64(parts[5]);
                let cost_want = parse_f64(parts[7]);
                let (team, stop) = match mode {
                    "aware" => greedy_router(diff, budget, false, &[]),
                    "random" => greedy_router(diff, budget, true, &draws),
                    _ => panic!("unknown mode"),
                };
                let want_team = parse_team(team_s);
                if team != want_team {
                    mismatches.push(format!(
                        "line {lineno}: Q {diff} B={budget} {mode}: team {team:?} != {want_team:?}"
                    ));
                }
                if stop != stop_want {
                    mismatches.push(format!(
                        "line {lineno}: Q {diff} B={budget} {mode}: stop {stop} != {stop_want}"
                    ));
                }
                let cost = team_cost(&team);
                // Tolerance, not bit equality: Rust's f64 sum() of an
                // empty team is -0.0, and Python 3.12's sum() uses
                // compensated (Neumaier) summation, so multi-agent
                // totals can differ in the last ulp. Single
                // call_cost values are still compared exactly (C cases).
                if (cost - cost_want).abs() > 1e-12 {
                    mismatches.push(format!(
                        "line {lineno}: Q {diff} B={budget} {mode}: cost {cost:?} != {cost_want:?}"
                    ));
                }
                let exp = expected_team_success(&team, diff);
                if (exp - exp_want).abs() > 1e-6 {
                    mismatches.push(format!(
                        "line {lineno}: Q {diff} B={budget} {mode}: exp {exp:.9} != {exp_want:.9}"
                    ));
                }
            }
            other => panic!("unknown case type {other} on line {lineno}"),
        }
    }

    println!("parity: {n_c} cost, {n_e} expected-success, {n_q} router cases");
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{}",
        mismatches.len(),
        mismatches.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}

#[test]
fn unit_cost_utility_templates() {
    use meter_router::{remaining_budget, template_graph, utility};
    assert!((call_cost(0, 0, 0) - (0.06 * 2000.0 + 0.19 * 1200.0) / 1e6).abs() < 1e-12);
    assert!((remaining_budget(5e-3, &[1e-3, 2e-3]) - 2e-3).abs() < 1e-15);
    assert!((utility(true, 1e-3, 5e-3, 0.5) - 0.9).abs() < 1e-12);
    assert_eq!(template_graph("chain", 3), vec![vec![], vec![0], vec![1]]);
    assert_eq!(template_graph("dense", 4).iter().map(|p| p.len()).sum::<usize>(), 6);
    // erf approximation sanity: erf(0) = 0, erf(1) ~ 0.8427, erf(3) ~ 1.
    assert!(meter_router::erf_approx(0.0).abs() < 1e-12);
    assert!((meter_router::erf_approx(1.0) - 0.84270079).abs() < 1e-6);
    assert!((meter_router::erf_approx(3.0) - 0.99997791).abs() < 1e-6);
}
